package com.retail.order;
import jakarta.annotation.Priority; import jakarta.ws.rs.Priorities; import jakarta.ws.rs.container.*; import jakarta.ws.rs.core.*; import jakarta.ws.rs.ext.Provider; import org.eclipse.microprofile.config.inject.ConfigProperty; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.*;
@Provider @PreMatching @Priority(Priorities.AUTHENTICATION) public class SecurityFilter implements ContainerRequestFilter,ContainerResponseFilter { @ConfigProperty(name="app.internal-key") String key; public void filter(ContainerRequestContext c){String id=Optional.ofNullable(c.getHeaderString("X-Request-Id")).filter(v->!v.isBlank()&&v.length()<=80).orElseGet(()->UUID.randomUUID().toString());c.setProperty("requestId",id);} public void filter(ContainerRequestContext c,ContainerResponseContext r){r.getHeaders().putSingle("X-Request-Id",c.getProperty("requestId"));} public boolean internal(String given){return MessageDigest.isEqual(key.getBytes(StandardCharsets.UTF_8),Optional.ofNullable(given).orElse("").getBytes(StandardCharsets.UTF_8));}}
